```python
class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        current_node = self.root
        for char in word:
            if char not in current_node.children:
                current_node.children[char] = TrieNode()
            current_node = current_node.children[char]
        current_node.is_end_of_word = True

    def search(self, word: str) -> bool:
        current_node = self.root
        for char in word:
            if char not in current_node.children:
                return False
            current_node = current_node.children[char]
        return current_node.is_end_of_word

    def _find_words_with_prefix(self, node: TrieNode, prefix: str, results: list):
        # If this node marks the end of a word, add the prefix to results
        if node.is_end_of_word:
            results.append(prefix)

        # Recur for all children
        for char, child_node in node.children.items():
            self._find_words_with_prefix(child_node, prefix + char, results)

    def autocomplete(self, prefix: str) -> list:
        current_node = self.root
        results = []

        # Navigate to the end of the prefix in the Trie
        for char in prefix:
            if char not in current_node.children:
                return []  # No completions if the prefix does not exist
            current_node = current_node.children[char]

        # Find all words with the given prefix
        self._find_words_with_prefix(current_node, prefix, results)

        # Return the top 3 completions in lexical order
        return sorted(results)[:3]

