class LRUCache {
private:
    std::unordered_map<int, Node*> cache; // Key to Node mapping
    DoublyLinkedList *list;
    int capacity;

public:
    LRUCache(int capacity) {
        this->capacity = capacity;
        list = new DoublyLinkedList();
    }

    int get(int key) {
        if (cache.find(key) != cache.end()) {
            Node *node = cache[key];
            list->moveToHead(node); // Move accessed node to the head
            return node->value;
        }
        return -1; // Key not found
    }

    void put(int key, int value) {
        if (cache.find(key) != cache.end()) {
            // Update the value and move to head
            Node *node = cache[key];
            node->value = value;
            list->moveToHead(node);
        } else {
            // Create a new node
            Node *newNode = new Node(key, value);
            cache[key] = newNode; // Add new key to cache

            list->addNode(newNode); // Add node to the head

            if (cache.size() > capacity) {
                // Evict the least recently used (tail)
                Node *tailNode = list->popTail();
                if (tailNode) {
                    cache.erase(tailNode->key); // Remove from cache
                    delete tailNode; // Clean up the evicted node
                }
            }
        }
    }

    ~LRUCache() {
        delete list; // Clean up the doubly linked list
        for (auto it : cache) {
            delete it.second; // Clean up remaining nodes in the cache
