```python
class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_of_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        """Insert a word into the trie."""
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_of_word = True

    def search(self, word: str) -> bool:
        """Search for a word in the trie. Returns True if the word exists, False otherwise."""
        node = self.root
        for char in word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.is_end_of_word

    def _find_words_with_prefix(self, node: TrieNode, prefix: str, results: list) -> None:
        """Helper method to find all words with a given prefix."""
        if node.is_end_of_word:
            results.append(prefix)
        for char, child_node in node.children.items():
            self._find_words_with_prefix(child_node, prefix + char, results)

    def autocomplete(self, prefix: str) -> list:
        """Return a list of words that start with the given prefix."""
        node = self.root
        for char in prefix:
            if char not in node.children:
                return []  # No completions found
            node = node.children[char]

        results = []
        self._find_words_with_prefix(node, prefix, results)
        return sorted(results)[:3]  # Return top 3 suggestions sorted lexicographically

